-- Standard courses for Jana Academy
INSERT INTO courses (id, title_ru, title_kz, description_ru, description_kz, track, target_role, department_id, lessons) VALUES
  (1, 'Информационная безопасность', 'Ақпараттық қауіпсіздік', 'Базовые правила защиты данных компании', 'Компания деректерін қорғаудың негізгі ережелері', 'job', 'all', NULL, '[
    {"id": 1, "title": "Парольная политика и защита учетных записей", "content": "Все корпоративные пароли сотрудников JanaPost должны состоять минимум из 8 символов, включая заглавные и строчные буквы, цифры и специальные символы. Запрещается использовать дату рождения и простые последовательности. Смена пароля производится каждые 90 дней."},
    {"id": 2, "title": "Защита от фишинга и социальной инженерии", "content": "Фишинг — главный вектор кибератак. Всегда проверяйте адрес отправителя в почте (janapost.kz). Никогда не переходите по подозрительным ссылкам и не открывайте неизвестные вложения. Обо всех подозрениях сообщайте в IT."},
    {"id": 3, "title": "Конфиденциальность данных клиентов и отправлений", "content": "Персональные данные клиентов JanaPost защищены законом. Запрещено фотографировать накладные на личный телефон, пересылать сведения в нерабочие чаты или разглашать информацию третьим лицам."},
    {"id": 4, "title": "Безопасность рабочего места: Clean Desk & Clean Screen", "content": "Покидая рабочее место, обязательно блокируйте экран комбинацией Win + L. Бумажные накладные и документы храните в закрываемых шкафах. Запрещено подключать непроверенные личные накопители к рабочим ПК."}
  ]'::jsonb),
  (2, 'Стандарты сервиса JanaPost', 'JanaPost сервис стандарттары', 'Как мы работаем с клиентами и посылками', 'Біз клиенттермен және сәлемдемелермен қалай жұмыс істейміз', 'job', 'all', NULL, '[
    {"id": 1, "title": "Клиентоориентированность и культура обслуживания", "content": "Каждый клиент — наш партнер. Вступайте в диалог в течение 5 секунд, приветствуйте доброжелательно на казахском или русском языке. Стандарт времени ожидания в отделении — не более 7 минут."},
    {"id": 2, "title": "Регламент приемки, упаковки и маркировки посылок", "content": "Сверяйте габариты, вес и целостность упаковки. Хрупкие отправления маркируются лентой «Осторожно, хрупкое!» и упаковываются с пузырчатой пленкой. Штрих-код сканируется сразу при приеме для трекинга."},
    {"id": 3, "title": "Работа с рекламациями, претензиями и возвратами", "content": "При повреждении упаковки составляется коммерческий акт в системе JanaMen с фотофиксацией в присутствии клиента. Сохраняйте спокойствие и вежливость; передайте номер тикета для возмещения."},
    {"id": 4, "title": "Соблюдение сроков доставки OTD (On-Time Delivery)", "content": "Целевой норматив своевременной доставки OTD — не менее 98.5%. Экспресс-отправления передаются курьерам и магистральным рейсам в приоритетном порядке строго по расписанию."}
  ]'::jsonb)
ON CONFLICT (id) DO UPDATE SET lessons = EXCLUDED.lessons, track = EXCLUDED.track, target_role = EXCLUDED.target_role;

-- Standard Knowledge Base documents for HR-assistant
INSERT INTO kb_documents (id, title, section, url, content, keywords, lang) VALUES
  (1, 'Регламент ежегодных отпусков', 'Раздел 2. Расчёт отпуска', '/kb/vacation#calc', 'Ежегодный оплачиваемый отпуск составляет 24 календарных дня в год. Отпуск рассчитывается пропорционально отработанному времени: за каждый полный месяц работы начисляется 2 дня. Заявка подаётся через платформу не позднее чем за 14 дней до начала отпуска и согласовывается непосредственным руководителем.', 'отпуск отпуска рассчитывается расчет дни дней остаток ежегодный отдых', 'ru'),
  (2, 'Регламент ежегодных отпусков', 'Раздел 3. Порядок оформления', '/kb/vacation#apply', 'Для оформления отпуска откройте раздел «Мои заявки», выберите «Заявка на отпуск», укажите даты. Платформа проверит остаток дней. После согласования руководителем заявка передаётся в Documentolog и проводится в 1С:ЗУП.', 'оформить оформление заявка отпуск подать согласование', 'ru'),
  (3, 'Положение об авансе', 'Раздел 1. Условия выплаты', '/kb/advance#terms', 'Аванс выплачивается 15 числа каждого месяца. Заявка на дополнительный аванс подаётся через платформу, сумма не может превышать 50% оклада. Решение принимает руководитель подразделения.', 'аванс выплата зарплата сумма дата аванса', 'ru'),
  (4, 'Регламент больничных листов', 'Раздел 1. Действия работника', '/kb/sick#steps', 'При болезни уведомите руководителя в первый день нетрудоспособности. Электронный листок нетрудоспособности передаётся в HR в течение 3 рабочих дней после закрытия.', 'больничный больничные болезнь заболел лист нетрудоспособности', 'ru'),
  (5, 'Политика обучения Jana Academy', 'Раздел 1. Обязательное обучение', '/kb/academy#mandatory', 'Назначенные курсы необходимо пройти в течение 30 дней. По завершении курса проводится тест, проходной балл 70%. Результаты сохраняются в профиле работника.', 'обучение курс курсы тест академия проходной балл назначенное', 'ru'),
  (6, 'Жыл сайынғы демалыс регламенті', '2-бөлім. Демалысты есептеу', '/kb/vacation#calc', 'Жыл сайынғы ақылы демалыс жылына 24 күнтізбелік күнді құрайды. Әр толық жұмыс айы үшін 2 күн есептеледі. Өтінім демалыс басталуына 14 күн қалғанда платформа арқылы беріледі.', 'демалыс демалысты есептеу күн қалдық', 'kz')
ON CONFLICT (id) DO NOTHING;
